<template>
 <section ref="panelElement" tabindex="-1" class="aw aw-panel aw-source-panel">
  <h3>{{t('source')}}</h3>
  <p v-if="state.sourcePhase==='succeeded'&&state.receipt" role="status">{{t('saved')}} · {{t(state.receipt.sourceType)}} #{{state.receipt.sourceId}}</p>
  <p v-if="state.sourceReadPhase==='loading'" role="status">{{t('loading')}}</p>
  <p v-if="state.sourceReadPhase==='unavailable'" class="aw-notice" role="alert">{{t(state.sourcePhase==='succeeded'?'assessmentUnknown':'sourceUnavailable')}}</p><button v-if="state.sourceReadPhase==='unavailable'&&state.sourceLocator" type="button" @click="flow.readSource(state.sourceLocator.type,state.sourceLocator.id)">{{t('retryRead')}}</button>
  <div v-if="state.receipt" class="aw-controls"><router-link v-for="item in state.receipt.followUps||[]" :key="item.alertId" class="aw-link" :to="`/alert-workflows/${item.alertId}?patientId=${state.patientId}`">{{t('open')}} #{{item.alertId}}</router-link></div>
  <template v-if="source">
   <p>{{t(source.sourceType)}} #{{source.id}} · {{t('sourceRevision')}} {{source.sourceRevision}} · {{t('sourceVersion')}} {{source.sourceVersion}} · {{t(source.sourceStatus)}}</p>
   <p v-if="source.sourceStatus==='INVALIDATED'" class="aw-notice">{{t('invalidSource')}}</p><SourceValues :source="source" />
   <h3>{{t('assessment')}}</h3><p v-if="!source.assessments?.length">{{t('unknown')}}</p>
   <article v-for="assessment in source.assessments||[]" :key="assessment.metric"><strong>{{t(assessment.metric)}} · {{t(assessment.status)}}</strong><p>{{t('policy')}}: {{assessment.policyKey}}</p><dl><template v-for="(value,key) in assessment.thresholds||{}" :key="key"><dt>{{t(key)}}</dt><dd>{{t('withheld')}}</dd></template></dl><p v-if="assessment.status==='UNCLASSIFIABLE'" class="aw-notice">{{t('confirmContext')}}</p><p v-if="assessment.status==='NORMAL'">{{t('normalNoClosure')}}</p><p class="aw-notice">{{t('comparisonUnitUnavailable')}}</p><p v-if="assessment.period">{{t('period')}}: {{assessment.period}}</p></article>
   <div class="aw-controls"><button type="button" @click="loadHistory">{{t('sourceHistory')}}</button><template v-if="state.capabilities?.canAdopt"><button type="button" :disabled="locked" @click="begin('correct')">{{t('correct')}}</button><button type="button" :disabled="locked" @click="begin('invalidate')">{{t('invalidate')}}</button><button type="button" :disabled="locked||source.sourceStatus==='INVALIDATED'" @click="begin('adopt')">{{t('manual')}}</button></template></div>
   <form v-if="operation" @submit.prevent="save" class="aw-panel">
    <h3>{{t(operation==='correct'?'correct':operation==='invalidate'?'invalidate':'manual')}}</h3><p>{{t(operation==='adopt'?'manualHelp':'correctionHelp')}}</p>
    <p v-if="message" role="alert">{{t(message)}}</p><p v-if="state.sourcePhase==='uncertain'" class="aw-notice">{{t('uncertain')}}</p><p v-if="state.sourcePhase==='conflict'" class="aw-notice">{{t('conflict')}}</p><p v-if="state.sourcePhase==='rejected'" class="aw-notice">{{t('rejected')}}</p>
    <fieldset :disabled="locked">
     <label v-if="operation==='adopt'">{{t('metric')}}<select v-model="form.metric" required><option v-for="assessment in source.assessments||[]" :key="assessment.metric" :value="assessment.metric">{{t(assessment.metric)}} · {{t(assessment.status)}}</option></select></label>
     <template v-if="operation==='correct'"><p class="aw-notice">{{t('correctionMetadataReadOnly')}}</p>
      <template v-if="source.sourceType==='HEALTH_MEASUREMENT'"><label>{{t('metric')}}<select v-model="form.metricType"><option v-for="metric in ['BP','GLUCOSE','SPO2','WEIGHT','HEART_RATE','TEMPERATURE','CUSTOM']" :key="metric" :value="metric">{{t(metric)}}</option></select></label><label>{{t('primary')}}<input v-model.number="form.valuePrimary" type="number" step="any" required /></label><label v-if="form.metricType==='BP'">{{t('secondary')}}<input v-model.number="form.valueSecondary" type="number" step="1" required /></label><label>{{t('unit')}}<input v-model="form.unit" required /></label><label>{{t('measurementTime')}}<input v-model="form.measuredAt" type="datetime-local" step="0.000001" required /></label></template>
      <template v-else><label>{{t('measureType')}}<select v-model="form.measureType"><option value="BP">{{t('BP')}}</option><option value="BG">{{t('BG')}}</option><option value="BP_BG">{{t('BP_BG')}}</option></select></label><div class="aw-grid"><label>{{t('recordDate')}}<input v-model="form.recordDate" type="date" required /></label><label>{{t('recordTime')}}<input v-model="form.recordTime" type="time" step="0.000001" required /></label></div><template v-if="form.measureType!=='BG'"><label>{{t('systolic')}}<input v-model.number="form.systolicBp" type="number" step="1" required /></label><label>{{t('diastolic')}}<input v-model.number="form.diastolicBp" type="number" step="1" required /></label></template><template v-if="form.measureType!=='BP'"><label>{{t('glucose')}}<input v-model.number="form.bloodGlucose" type="number" step="any" required /></label><label>{{t('unit')}}<select v-model="form.bgUnit"><option value="mmol/L">mmol/L</option><option value="mg/dL">mg/dL</option></select></label><label>{{t('period')}}<input v-model="form.measurePeriod" /></label></template></template>
      <label>{{t('offset')}}<input v-model="form.offset" type="text" pattern="[+-][0-9]{2}:[0-9]{2}" placeholder="+08:00" required /></label><p>{{t('offsetHelp')}}</p>
     </template>
     <label>{{t('reason')}}<textarea v-model="form.reason" maxlength="1000" rows="3" required /></label>
    </fieldset>
    <div class="aw-controls"><button v-if="!['uncertain','conflict','rejected'].includes(state.sourcePhase)" type="submit" :disabled="locked">{{t('submit')}}</button><button v-if="state.sourcePhase==='uncertain'" type="button" @click="retry">{{t('retryOriginal')}}</button><button v-if="['conflict','rejected'].includes(state.sourcePhase)" type="button" @click="newDecision">{{t('newDecision')}}</button><button type="button" :disabled="locked" @click="operation=null">{{t('cancel')}}</button></div>
   </form>
   <template v-if="historyVisible"><h3>{{t('sourceHistory')}}</h3><article v-for="revision in state.sourceHistory" :key="revision.id"><p>{{t('sourceRevision')}} {{revision.sourceRevision}} · {{t(revision.sourceStatus)}}</p><p>{{t('recorder')}} #{{revision.recordedBy}} · {{t('occurred')}}: {{formatWorkflowTime(revision.occurredAt)}} · {{t('captured')}}: {{formatWorkflowTime(revision.recordedAt)}}</p><p>{{t('reason')}}: {{revision.correctionReason||'—'}}</p><SourceValues :source="revision.snapshot" /></article><p v-if="!state.sourceHistory.length">{{t('noResult')}}</p><button v-if="state.sourceCursor" type="button" @click="flow.loadSourceHistory(source.sourceType,source.id,state.sourceCursor)">{{t('more')}}</button></template>
  </template>
 </section>
</template>
<script setup>
import {formatWorkflowTime} from '@/utils/alertWorkflowTime'
import {computed,reactive,ref,watch,nextTick} from 'vue'
import {measurementInstant} from '@/utils/alertWorkflowForms'
import {t} from '@/utils/alertWorkflowCopy'
import SourceValues from './SourceValues.vue'
import './workflow.css'
const props=defineProps({flow:{type:Object,required:true}}),emit=defineEmits(['changed']),state=props.flow.state,source=computed(()=>state.source),operation=ref(null),form=reactive({}),historyVisible=ref(false),message=ref(null),panelElement=ref(null)
const locked=computed(()=>['submitting','uncertain'].includes(state.sourcePhase))
function begin(kind){if(locked.value||!state.capabilities?.canAdopt)return;operation.value=kind;message.value=null;Object.assign(form,{...source.value,reason:'',offset:'',metric:source.value.assessments?.[0]?.metric,measuredAt:source.value.measuredAt?.replace(' ','T')});if(['conflict','rejected'].includes(state.sourcePhase))return}
async function loadHistory(){historyVisible.value=true;await props.flow.loadSourceHistory(source.value.sourceType,source.value.id)}
function correction(){const s=source.value;if(s.sourceType==='HEALTH_MEASUREMENT')return {metricType:form.metricType,valuePrimary:form.valuePrimary,valueSecondary:form.metricType==='BP'?form.valueSecondary:null,unit:form.unit,measuredAt:form.measuredAt,sourceType:s.sourceKind,reason:form.reason,occurredAt:measurementInstant(form.measuredAt,form.offset)};return {recordDate:form.recordDate,recordTime:form.recordTime,measureType:form.measureType,systolicBp:form.measureType==='BG'?null:form.systolicBp,diastolicBp:form.measureType==='BG'?null:form.diastolicBp,bloodGlucose:form.measureType==='BP'?null:form.bloodGlucose,bgUnit:form.measureType==='BP'?null:form.bgUnit,measurePeriod:form.measureType==='BP'?null:form.measurePeriod,reason:form.reason,occurredAt:measurementInstant(`${form.recordDate}T${form.recordTime}`,form.offset)}}
async function execute(retry=false){message.value=null;try{const s=source.value,result=operation.value==='adopt'?await props.flow.adoptSource({sourceType:s.sourceType,sourceId:s.id,metric:form.metric,manualFollowUp:true,reason:form.reason},{retry}):await props.flow.saveSource(s.sourceType,retry?{}:operation.value==='invalidate'?{reason:form.reason}:correction(),{id:s.id,operation:operation.value,retry});if(result.status==='succeeded'){operation.value=null;emit('changed');if(historyVisible.value)await loadHistory()}else if(!['uncertain','conflict','rejected','stale'].includes(result.status))message.value='inputInvalid'}catch{message.value='inputInvalid'}}
const save=()=>execute(),retry=()=>execute(true)
async function newDecision(){const s=source.value,result=await props.flow.readSource(s.sourceType,s.id);if(result.status==='succeeded')props.flow.newDecision('source')}
defineExpose({async beginOperation(kind){if(kind)begin(kind);await nextTick();panelElement.value?.focus({preventScroll:true});panelElement.value?.scrollIntoView({behavior:'auto',block:'start'})}})
watch(()=>`${state.sourceLocator?.type}:${state.sourceLocator?.id}`,()=>{operation.value=null;historyVisible.value=false;Object.keys(form).forEach(k=>delete form[k])},{flush:'sync'})
watch(()=>state.patientId,()=>{operation.value=null;historyVisible.value=false;Object.keys(form).forEach(k=>delete form[k])},{flush:'sync'})
</script>
